# 检测 DevKit-LCD USB-UART，并尝试串口冒烟读数
# 用法：先插好【数据线】到板【USB to UART】口，再运行本脚本
#   powershell -ExecutionPolicy Bypass -File scripts\detect_and_smoke.ps1
# 可选：-WaitSec 60  等待板子插入；-Baud 1000000

param(
  [int]$WaitSec = 0,
  [int]$Baud = 1000000,
  [string]$Port = ""
)

function Get-BoardCandidates {
  Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue |
    Where-Object {
      $_.Name -match 'COM\d+' -and
      $_.Name -notmatch '蓝牙|Bluetooth|BTHENUM' -and
      (
        $_.Name -match 'CH34|WCH|USB-SERIAL|USB Serial|Silicon|CDC' -or
        $_.DeviceID -match 'VID_1A86|VID_067B|VID_10C4|CH34'
      )
    }
}

function Get-ComFromName([string]$name) {
  if ($name -match '(COM\d+)') { return $Matches[1] }
  return $null
}

Write-Host "==== Type-C / UART 检测 ====" -ForegroundColor Cyan
Write-Host "当前所有带 COM 的设备："
Get-CimInstance Win32_PnPEntity | Where-Object { $_.Name -match 'COM\d+' } |
  ForEach-Object { "  - $($_.Name)" }

$cands = @(Get-BoardCandidates)
if ($WaitSec -gt 0 -and $cands.Count -eq 0) {
  Write-Host "未发现板载串口，等待插入最多 ${WaitSec}s ..." -ForegroundColor Yellow
  $deadline = (Get-Date).AddSeconds($WaitSec)
  while ((Get-Date) -lt $deadline) {
    Start-Sleep -Seconds 2
    $cands = @(Get-BoardCandidates)
    if ($cands.Count -gt 0) { break }
    Write-Host "." -NoNewline
  }
  Write-Host ""
}

if (-not $Port) {
  if ($cands.Count -eq 0) {
    Write-Host @"

【结果】未检测到 DevKit USB-UART（CH340/CH34x 类）。
请检查：
1. 用数据线（非纯充电线）
2. 插板上丝印【USB to UART】口（不是另一个 Type-C）
3. 电源灯是否亮
4. 无新 COM 时安装 WCH CH34x 驱动后重插
然后再运行本脚本。可加： -WaitSec 60

"@ -ForegroundColor Red
    exit 2
  }
  $Port = Get-ComFromName $cands[0].Name
  Write-Host "选用疑似板口：$($cands[0].Name) -> $Port" -ForegroundColor Green
} else {
  Write-Host "使用指定端口：$Port" -ForegroundColor Green
}

# 尝试打开串口读几秒
Write-Host "==== 串口冒烟读取 (baud=$Baud) ====" -ForegroundColor Cyan
try {
  $sp = New-Object System.IO.Ports.SerialPort $Port, $Baud, 'None', 8, 'One'
  $sp.ReadTimeout = 500
  $sp.WriteTimeout = 500
  $sp.DtrEnable = $false
  $sp.RtsEnable = $false
  $sp.Open()
  Write-Host "已打开 $Port。请在 8 秒内按板上【复位】键..." -ForegroundColor Yellow
  $buf = New-Object System.Text.StringBuilder
  $end = (Get-Date).AddSeconds(8)
  while ((Get-Date) -lt $end) {
    try {
      $n = $sp.BytesToRead
      if ($n -gt 0) {
        $chunk = $sp.ReadExisting()
        [void]$buf.Append($chunk)
        Write-Host -NoNewline $chunk
      }
    } catch {}
    Start-Sleep -Milliseconds 50
  }
  $sp.Close()
  $text = $buf.ToString()
  Write-Host ""
  if ($text.Length -gt 0) {
    Write-Host "【结果】收到 $($text.Length) 字符串口数据。" -ForegroundColor Green
    if ($text -match 'nsh>|NuttShell|SF32|vela|siFli|SiFli') {
      Write-Host "【结果】疑似系统控制台输出，板级串口冒烟通过。" -ForegroundColor Green
      exit 0
    } else {
      Write-Host "【结果】有数据但未匹配 NSH 关键字。可换波特率 -Baud 115200 再试，或确认固件。" -ForegroundColor Yellow
      exit 0
    }
  } else {
    Write-Host "【结果】超时无数据。试：按复位；-Baud 115200；确认未被其他程序占用。" -ForegroundColor Yellow
    exit 3
  }
} catch {
  Write-Host "【结果】打开串口失败：$($_.Exception.Message)" -ForegroundColor Red
  exit 4
}

# 使用 sftool 烧录（需已有固件文件）。默认只做探测，真正烧录需传 -Firmware。
# 例：
#   powershell -ExecutionPolicy Bypass -File scripts\flash_sf32.ps1
#   powershell -ExecutionPolicy Bypass -File scripts\flash_sf32.ps1 -Port COM9 -Firmware "D:\fw\app.bin@0x12020000"

param(
  [string]$Port = "",
  [string]$Firmware = "",
  [string]$Chip = "SF32LB52",
  [int]$Baud = 1000000
)

$root = Split-Path (Split-Path $PSScriptRoot -Parent) -ErrorAction SilentlyContinue
if (-not $root) { $root = "e:\openvela\contest2026_313_bianyuanxingzhe" }
$sftool = Get-ChildItem "$root\tools\sftool" -Recurse -Filter sftool.exe -ErrorAction SilentlyContinue |
  Select-Object -First 1 -ExpandProperty FullName

if (-not $sftool) {
  Write-Host "未找到 tools/sftool/sftool.exe，请先下载 sftool。" -ForegroundColor Red
  exit 1
}

Write-Host "sftool: $sftool"

if (-not $Port) {
  $cands = Get-CimInstance Win32_PnPEntity | Where-Object {
    $_.Name -match 'COM\d+' -and $_.Name -match 'CH34|WCH|USB-SERIAL|USB Serial'
  }
  if ($cands) {
    if ($cands[0].Name -match '(COM\d+)') { $Port = $Matches[1] }
  }
}

if (-not $Port) {
  Write-Host "未指定且未自动发现板 COM。请插板后： -Port COMx" -ForegroundColor Red
  Write-Host "或先运行 scripts\detect_and_smoke.ps1"
  exit 2
}

Write-Host "探测芯片：$Chip @ $Port"
& $sftool -c $Chip -p $Port --baud $Baud 2>&1 | Out-Host

if (-not $Firmware) {
  Write-Host @"

【烧录未执行】原因：还没有竞赛固件镜像。
需要先在 Ubuntu 全量 openvela 工程编译出 bin，例如：
  ./build.sh vendor/.../sf32lb52_devkit_lcd/ --cmake -j8
然后再例如：
  .\scripts\flash_sf32.ps1 -Port $Port -Firmware "app.bin@0x12020000"

Windows 也可用思澈 Impeller 图形工具烧录（插 USB-UART，监控后按复位）。

"@ -ForegroundColor Yellow
  exit 0
}

Write-Host "开始 write_flash: $Firmware"
& $sftool -c $Chip -p $Port --baud $Baud write_flash $Firmware
exit $LASTEXITCODE

param(
  [int]$WaitSec = 0,
  [int]$Baud = 1000000,
  [string]$Port = ""
)

function Get-BoardCandidates {
  Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue |
    Where-Object {
      $_.Name -match 'COM\d+' -and
      $_.Name -notmatch 'Bluetooth|BTHENUM' -and
      (
        $_.Name -match 'CH34|WCH|USB-SERIAL|USB Serial|Silicon|CDC' -or
        $_.DeviceID -match 'VID_1A86|VID_067B|VID_10C4|CH34'
      )
    }
}

function Get-ComFromName([string]$name) {
  if ($name -match '(COM\d+)') { return $Matches[1] }
  return $null
}

Write-Host "==== USB-UART detect ====" -ForegroundColor Cyan
Write-Host "All COM devices:"
Get-CimInstance Win32_PnPEntity | Where-Object { $_.Name -match 'COM\d+' } |
  ForEach-Object { "  - $($_.Name)" }

$cands = @(Get-BoardCandidates)
if ($WaitSec -gt 0 -and $cands.Count -eq 0) {
  Write-Host "No board COM yet. Waiting up to ${WaitSec}s. Plug data cable to USB-to-UART now..." -ForegroundColor Yellow
  $deadline = (Get-Date).AddSeconds($WaitSec)
  while ((Get-Date) -lt $deadline) {
    Start-Sleep -Seconds 2
    $cands = @(Get-BoardCandidates)
    if ($cands.Count -gt 0) { break }
    Write-Host "." -NoNewline
  }
  Write-Host ""
}

if (-not $Port) {
  if ($cands.Count -eq 0) {
    Write-Host ""
    Write-Host "[FAIL] No DevKit USB-UART (CH340/CH34x) found." -ForegroundColor Red
    Write-Host "Checklist:"
    Write-Host "  1) Use a DATA Type-C cable (not charge-only)"
    Write-Host "  2) Plug the port labeled USB to UART (not the other Type-C)"
    Write-Host "  3) Power LED should be on"
    Write-Host "  4) If still no COM, install WCH CH34x driver and replug"
    Write-Host "Then rerun with: -WaitSec 60"
    exit 2
  }
  $Port = Get-ComFromName $cands[0].Name
  Write-Host "Selected: $($cands[0].Name) -> $Port" -ForegroundColor Green
} else {
  Write-Host "Using port: $Port" -ForegroundColor Green
}

Write-Host "==== Serial smoke read (baud=$Baud) ====" -ForegroundColor Cyan
try {
  $sp = New-Object System.IO.Ports.SerialPort $Port, $Baud, 'None', 8, 'One'
  $sp.ReadTimeout = 500
  $sp.WriteTimeout = 500
  $sp.DtrEnable = $false
  $sp.RtsEnable = $false
  $sp.Open()
  Write-Host "Opened $Port. Press RESET on board within 8 seconds..." -ForegroundColor Yellow
  $buf = New-Object System.Text.StringBuilder
  $end = (Get-Date).AddSeconds(8)
  while ((Get-Date) -lt $end) {
    try {
      if ($sp.BytesToRead -gt 0) {
        $chunk = $sp.ReadExisting()
        [void]$buf.Append($chunk)
        Write-Host -NoNewline $chunk
      }
    } catch {}
    Start-Sleep -Milliseconds 50
  }
  $sp.Close()
  $text = $buf.ToString()
  Write-Host ""
  if ($text.Length -gt 0) {
    Write-Host "[OK] Received $($text.Length) chars." -ForegroundColor Green
    if ($text -match 'nsh>|NuttShell|SF32|vela|siFli|SiFli') {
      Write-Host "[PASS] Console-like output detected." -ForegroundColor Green
      exit 0
    }
    Write-Host "[WARN] Data received but no NSH keyword. Try -Baud 115200 or check firmware." -ForegroundColor Yellow
    exit 0
  }
  Write-Host "[WARN] No data. Press reset; try -Baud 115200; close other serial apps." -ForegroundColor Yellow
  exit 3
} catch {
  Write-Host "[FAIL] Open serial failed: $($_.Exception.Message)" -ForegroundColor Red
  exit 4
}

